    async def buy_domains(
        self,
        *,
        domains: list[str],
        duration_in_years: int | None = None,
        project_id: str | None = None,
        owner_contact_id: str | None = None,
        owner_contact: NewContact | None = None,
        administrative_contact_id: str | None = None,
        administrative_contact: NewContact | None = None,
        technical_contact_id: str | None = None,
        technical_contact: NewContact | None = None,
        auto_renew: bool | None = None,
    ) -> OrderResponse:
        """
        Purchase domains

        Request the registration of domain names.
        You can provide a domain's already existing contact or a new contact.

        Args:
            domains: List of domains to purchase.
            duration_in_years: Duration in years for the domain registration. Subject to
                TLD-specific minimum and maximum constraints.
            project_id: Project ID to create the domains in.
            owner_contact_id: ID of the existing contact to use as the domain's owner.
                Precisely one of owner_contact_id, owner_contact can be set.
            owner_contact: New contact to create and use as the domain's owner.
                Precisely one of owner_contact_id, owner_contact can be set.
            administrative_contact_id: ID of the existing contact to use as the domain's
                administrative contact. Optional; falls back to the owner contact if
                omitted. Precisely one of administrative_contact_id,
                administrative_contact can be set.
            administrative_contact: New contact to create and use as the domain's
                administrative contact. Optional; falls back to the owner contact if
                omitted. Precisely one of administrative_contact_id,
                administrative_contact can be set.
            technical_contact_id: ID of the existing contact to use as the domain's
                technical contact. Optional; falls back to the owner contact if omitted.
                Precisely one of technical_contact_id, technical_contact can be set.
            technical_contact: New contact to create and use as the domain's technical
                contact. Optional; falls back to the owner contact if omitted. Precisely
                one of technical_contact_id, technical_contact can be set.
            auto_renew: Enable the `auto renew` feature for all the requested domains.
                This means the domain will be automatically renewed before its expiry
                date.
        """
        data = await self._client.request_json(
            "POST",
            "/domain/v2beta1/buy-domains",
            body={
                "domains": domains,
                "duration_in_years": duration_in_years,
                "project_id": self._client.project_id(project_id),
                "owner_contact_id": owner_contact_id,
                "owner_contact": owner_contact,
                "administrative_contact_id": administrative_contact_id,
                "administrative_contact": administrative_contact,
                "technical_contact_id": technical_contact_id,
                "technical_contact": technical_contact,
                "auto_renew": auto_renew,
            },
        )
        return OrderResponse.model_validate(data)

