    async def trade_domain(
        self,
        *,
        domain: str,
        project_id: str | None = None,
        new_owner_contact_id: str | None = None,
        new_owner_contact: NewContact | None = None,
    ) -> OrderResponse:
        """
        Trade a domain's contact

        Request to change a domain's contact owner.<br/>
        If you specify the `organization_id` of the domain's new owner, the contact will
        change from the current owner's Scaleway account to the new owner's Scaleway
        account.<br/>
        If the new owner's current contact information is not available, the first ever
        contact they have created for previous domains is taken into account to operate
        the change.<br/>
        If the new owner has never created a contact to register domains before, an
        error message displays.

        Args:
            domain: The domain name to trade (change of owner/registrant).
            project_id: Project ID to associate with the domain after the trade. Also
                used to filter the new owner's contacts.
            new_owner_contact_id: ID of the existing contact to use as the domain's new
                owner. Precisely one of new_owner_contact_id, new_owner_contact can be
                set.
            new_owner_contact: New contact to create and use as the domain's new owner.
                Precisely one of new_owner_contact_id, new_owner_contact can be set.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path("/domain/v2beta1/domains/{domain}/trade", domain=domain),
            body={
                "project_id": self._client.project_id(project_id),
                "new_owner_contact_id": new_owner_contact_id,
                "new_owner_contact": new_owner_contact,
            },
        )
        return OrderResponse.model_validate(data)

